import React from 'react';
import Header from '../Components/Header/Header';
import { Banner } from '../Components/Banner/Banner'; // Added curly braces
import { Posts } from '../Components/Posts/Posts'; // Added curly braces
import Footer from '../Components/Footer/Footer';

function Home() {
  return (
    <div className="homeParentDiv">
      <Header />
      <Banner />
      <Posts />
      <Footer />
    </div>
  );
}

export default Home;
